// Applies the TiDB migrations (./migrations, generated by drizzle-kit from
// ./schema.js) to TiDB Cloud: creates the app's database if it's missing, then
// runs the migrations it hasn't had yet (Drizzle records them in the table
// __drizzle_migrations). Node only, since it reads the files. From server/:
//   DB_PASSWORD='mysql://…' npm run db:migrate        (database TAU_DB_NAME, default tau)
// Run it before deploying a version that brings a new migration.
import { fileURLToPath, pathToFileURL } from 'node:url';
import { connect as driverConnect } from '@tidbcloud/serverless';
import { drizzle } from 'drizzle-orm/tidb-serverless';
import { migrate } from 'drizzle-orm/tidb-serverless/migrator';
import { checkTidbSettings, DEFAULT_DATABASE } from './client.js';

export const MIGRATIONS = fileURLToPath(new URL('./migrations', import.meta.url));

/** `connect` is the driver's (tests pass a fake). */
export async function migrateTidb(url, { database = DEFAULT_DATABASE, connect = driverConnect } = {}) {
  checkTidbSettings(url, database);
  await connect({ url }).execute(`CREATE DATABASE IF NOT EXISTS \`${database}\``);
  await migrate(drizzle({ client: connect({ url, database }) }), { migrationsFolder: MIGRATIONS });
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const database = process.env.TAU_DB_NAME || DEFAULT_DATABASE;
  await migrateTidb(process.env.DB_PASSWORD, { database });
  console.log(`TiDB: database ${database} is up to date`);
}
